=head2 Google::Iam::Admin::V1::Iam::ServiceAccountKey

Represents a service account key.

A service account has two sets of key-pairs: user-managed, and
system-managed.

User-managed key-pairs can be created and deleted by users.  Users are
responsible for rotating these keys periodically to ensure security of
their service accounts.  Users retain the private key of these key-pairs,
and Google retains ONLY the public key.

System-managed keys are automatically rotated by Google, and are used for
signing for a maximum of two weeks. The rotation process is probabilistic,
and usage of the new key will gradually ramp up and down over the key's
lifetime.

If you cache the public key set for a service account, we recommend that you
update the cache every 15 minutes. User-managed keys can be added and removed
at any time, so it is important to update the cache frequently. For
Google-managed keys, Google will publish a key at least 6 hours before it is
first used for signing and will keep publishing it for at least 6 hours after
it was last used for signing.

Public keys for all service accounts are also published at the OAuth2
Service Account API.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

The resource name of the service account key in the following format
`projects/{PROJECT_ID}/serviceAccounts/{ACCOUNT}/keys/{key}`.

=item * C<< $msg->private_key_type() >> / C<< $msg->private_key_type($value) >>

Type: C<Enum> (L<Google::Iam::Admin::V1::ServiceAccountPrivateKeyType>)

The output format for the private key.
Only provided in `CreateServiceAccountKey` responses, not
in `GetServiceAccountKey` or `ListServiceAccountKey` responses.

Google never exposes system-managed private keys, and never retains
user-managed private keys.

=item * C<< $msg->key_algorithm() >> / C<< $msg->key_algorithm($value) >>

Type: C<Enum> (L<Google::Iam::Admin::V1::ServiceAccountKeyAlgorithm>)

Specifies the algorithm (and possibly key size) for the key.

=item * C<< $msg->private_key_data() >> / C<< $msg->private_key_data($value) >>

Type: C<Bytes>

The private key data. Only provided in `CreateServiceAccountKey`
responses. Make sure to keep the private key data secure because it
allows for the assertion of the service account identity.
When base64 decoded, the private key data can be used to authenticate with
Google API client libraries and with
<a href="/sdk/gcloud/reference/auth/activate-service-account">gcloud
auth activate-service-account</a>.

=item * C<< $msg->public_key_data() >> / C<< $msg->public_key_data($value) >>

Type: C<Bytes>

The public key data. Only provided in `GetServiceAccountKey` responses.

=item * C<< $msg->valid_after_time() >> / C<< $msg->valid_after_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

The key can be used after this timestamp.

=item * C<< $msg->valid_before_time() >> / C<< $msg->valid_before_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

The key can be used before this timestamp.
For system-managed key pairs, this timestamp is the end time for the
private key signing operation. The public key could still be used
for verification for a few hours after this time.

=item * C<< $msg->key_origin() >> / C<< $msg->key_origin($value) >>

Type: C<Enum> (L<Google::Iam::Admin::V1::ServiceAccountKeyOrigin>)

The key origin.

=item * C<< $msg->key_type() >> / C<< $msg->key_type($value) >>

Type: C<Enum> (L<Google::Iam::Admin::V1::ListServiceAccountKeysRequest::KeyType>)

The key type.

=item * C<< $msg->disabled() >> / C<< $msg->disabled($value) >>

Type: C<Bool>

The key status.

=back

