=head2 Google::Iam::Admin::V1::Iam::Role

A role in the Identity and Access Management API.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

The name of the role.

When Role is used in CreateRole, the role name must not be set.

When Role is used in output and other input such as UpdateRole, the role
name is the complete path, e.g., roles/logging.viewer for predefined roles
and organizations/{ORGANIZATION_ID}/roles/logging.viewer for custom roles.

=item * C<< $msg->title() >> / C<< $msg->title($value) >>

Type: C<String>

Optional. A human-readable title for the role.  Typically this
is limited to 100 UTF-8 bytes.

=item * C<< $msg->description() >> / C<< $msg->description($value) >>

Type: C<String>

Optional. A human-readable description for the role.

=item * C<< $msg->included_permissions() >> / C<< $msg->included_permissions($value) >>

Type: C<String>

The names of the permissions this role grants when bound in an IAM policy.

=item * C<< $msg->stage() >> / C<< $msg->stage($value) >>

Type: C<Enum> (L<Google::Iam::Admin::V1::Role::RoleLaunchStage>)

The current launch stage of the role. If the `ALPHA` launch stage has been
selected for a role, the `stage` field will not be included in the
returned definition for the role.

=item * C<< $msg->etag() >> / C<< $msg->etag($value) >>

Type: C<Bytes>

Used to perform a consistent read-modify-write.

=item * C<< $msg->deleted() >> / C<< $msg->deleted($value) >>

Type: C<Bool>

The current deleted state of the role. This field is read only.
It will be ignored in calls to CreateRole and UpdateRole.

=back

=head3 Enum: Role::RoleLaunchStage

=over 4

=item * C<ALPHA> => C<0>

=item * C<BETA> => C<1>

=item * C<GA> => C<2>

=item * C<DEPRECATED> => C<4>

=item * C<DISABLED> => C<5>

=item * C<EAP> => C<6>

=back

