=head2 Google::Iam::Admin::V1::Iam::LintPolicyRequest

The request to lint a Cloud IAM policy object.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->full_resource_name() >> / C<< $msg->full_resource_name($value) >>

Type: C<String>

The full resource name of the policy this lint request is about.

The name follows the Google Cloud Platform (GCP) resource format.
For example, a GCP project with ID `my-project` will be named
`//cloudresourcemanager.googleapis.com/projects/my-project`.

The resource name is not used to read the policy instance from the Cloud
IAM database. The candidate policy for lint has to be provided in the same
request object.

=item * C<< $msg->condition() >> / C<< $msg->condition($value) >>

Type: C<Message> (L<Google::Type::Expr::Expr>)

[google.iam.v1.Binding.condition] [google.iam.v1.Binding.condition] object to be linted.

=back

=head2 Google::Iam::Admin::V1::Iam::LintResult

Structured response of a single validation unit.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->level() >> / C<< $msg->level($value) >>

Type: C<Enum> (L<Google::Iam::Admin::V1::LintResult::Level>)

The validation unit level.

=item * C<< $msg->validation_unit_name() >> / C<< $msg->validation_unit_name($value) >>

Type: C<String>

The validation unit name, for instance
"lintValidationUnits/ConditionComplexityCheck".

=item * C<< $msg->severity() >> / C<< $msg->severity($value) >>

Type: C<Enum> (L<Google::Iam::Admin::V1::LintResult::Severity>)

The validation unit severity.

=item * C<< $msg->field_name() >> / C<< $msg->field_name($value) >>

Type: C<String>

The name of the field for which this lint result is about.

For nested messages `field_name` consists of names of the embedded fields
separated by period character. The top-level qualifier is the input object
to lint in the request. For example, the `field_name` value
`condition.expression` identifies a lint result for the `expression` field
of the provided condition.

=item * C<< $msg->location_offset() >> / C<< $msg->location_offset($value) >>

Type: C<Int32>

0-based character position of problematic construct within the object
identified by `field_name`. Currently, this is populated only for condition
expression.

=item * C<< $msg->debug_message() >> / C<< $msg->debug_message($value) >>

Type: C<String>

Human readable debug message associated with the issue.

=back

=head3 Enum: LintResult::Level

=over 4

=item * C<LEVEL_UNSPECIFIED> => C<0>

=item * C<CONDITION> => C<3>

=back

=head3 Enum: LintResult::Severity

=over 4

=item * C<SEVERITY_UNSPECIFIED> => C<0>

=item * C<ERROR> => C<1>

=item * C<WARNING> => C<2>

=item * C<NOTICE> => C<3>

=item * C<INFO> => C<4>

=item * C<DEPRECATED> => C<5>

=back

=head2 Google::Iam::Admin::V1::Iam::LintPolicyResponse

The response of a lint operation. An empty response indicates
the operation was able to fully execute and no lint issue was found.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->lint_results() >> / C<< $msg->lint_results($value) >>

Type: C<Message> (L<Google::Iam::Admin::V1::Iam::LintResult>)

List of lint results sorted by `severity` in descending order.

=back

